557	        String number = claim.getShownNumber();
558	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
559	        String due = null;
560	        if (next == ClaimStatus.SETTLED) {
561	            BigDecimal fixed = dueNow(sheetId, claim, owner);
562	            if (access.canSettle(sheetId, user, fixed)) {
563	                claim.setSettledDue(fixed);
564	                due = fixed == null ? "n/a" : fixed.toPlainString();
565	            } else {
566	                next = ClaimStatus.PENDING;
567	            }
568	        }
569	        claim.setStatus(next);
570	        claims.flush();
571	        String person = owner == null ? "" : owner.getName();
572	        String event = switch (next) {
573	            case OPEN -> "CLAIM_OPENED";
574	            case PENDING -> "CLAIM_PENDING";
575	            case SETTLED -> "CLAIM_SETTLED";
576	            case VOID -> "CLAIM_VOIDED";
577	            case DRAFT -> throw new IllegalStateException();
578	        };
579	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
580	        rollup.changed(sheetId, user, before);
581	        return claim.getPersonId();
582	    }
583	
584	    /**
585	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
586	     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
587	     * closed period is refused and nothing changes. Returns the person it belongs to.
588	     */
589	    @Transactional
590	    public long approve(String sheetId, String user, long claimId) {
591	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
592	        if (user.equals(claim.getOpenedBy())) {
593	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
594	        }
595	        Rollup.Figures before = rollup.figures(sheetId);
596	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
597	        BigDecimal fixed = dueNow(sheetId, claim, owner);
598	        claim.setSettledDue(fixed);
599	        claim.setStatus(ClaimStatus.SETTLED);
600	        claims.flush();
601	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
602	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
603	        rollup.changed(sheetId, user, before);
604	        return claim.getPersonId();
605	    }
606	
607	    /**
608	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
609	     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
610	     * period is refused and nothing changes. Returns the person it belongs to.
611	     */
612	    @Transactional
613	    public long reject(String sheetId, String user, long claimId, String reason) {
614	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
615	        Rollup.Figures before = rollup.figures(sheetId);
616	        claim.setStatus(ClaimStatus.OPEN);
617	        claims.flush();
618	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
619	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
620	                claim.getDate(), claim.getShownNumber(), null, reason));
621	        rollup.changed(sheetId, user, before);
622	        return claim.getPersonId();
623	    }
624	
625	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
626	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
627	        Claim claim = claim(sheetId, claimId);
628	        if (claim.getStatus() != ClaimStatus.PENDING) {
629	            throw new ResponseStatusException(HttpStatus.CONFLICT,
630	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
631	        }
632	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
633	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
634	        }
635	        return claim;
636	    }
637	
638	    private Claim claim(String sheetId, long claimId) {
639	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
640	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
641	        periods.requireOpen(sheetId, claim.getDate());
642	        return claim;
643	    }
644	
645	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
646	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
647	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
648	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
649	    }
650	
651	    /**
652	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
653	     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
654	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
655	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
656	     */
657	    private void giveNumber(String sheetId, Claim claim) {
658	        LocalDate from = sheets.periodNumberingFrom(sheetId);
659	        if (from == null || sheets.today(sheetId).isBefore(from)) {
660	            claim.setNumber(sheets.nextClaimNumber(sheetId));
661	            return;
662	        }
663	        sheetRows.lockById(sheetId);
664	        Period period = periods.list(sheetId).stream().filter(p -> p.contains(claim.getDate()))
665	                .findFirst().orElse(null);
666	        String sequence = period == null ? "X" : "P" + period.getId();
667	        int n = claims.lastInSequence(sheetId, sequence) + 1;
668	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
669	    }
670	
671	    /**
672	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
673	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
674	     * correction corrects (its rounding goes by it); null for any other claim.
675	     */
676	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
677	        if (amount.signum() >= 0) {
678	            if (corrects != null) {
679	                throw new ResponseStatusException(HttpStatus.CONFLICT,
680	                        "Only a correction (a negative amount) names a claim it corrects");
681	            }
682	            return null;
683	        }
684	        if (corrects == null) {
685	            throw new ResponseStatusException(HttpStatus.CONFLICT,
686	                    "A negative amount is a correction; name the number of the settled claim it corrects");
687	        }
688	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
689	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
690	                .map(Claim::getDate).findFirst()
691	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
692	                        "Claim " + corrects + " is not a settled claim of this person"));
693	    }
694	
695	    /** Refuse a claim dated after its person's retirement date. */
696	    private static void requireNotRetired(Person person, LocalDate date) {
697	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
698	            throw new ResponseStatusException(HttpStatus.CONFLICT,
699	                    person.getName() + " is retired from " + person.getRetiredFrom()
700	                            + "; a claim cannot be dated after that");
701	        }
702	    }
703	}
