745	package net.officefloor.hq.app.claim;
746	
747	/**
748	 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling
749	 * one above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (back to
750	 * OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). Only OPEN, PENDING and SETTLED claims count
751	 * toward what is claimed.
752	 */
753	public enum ClaimStatus {
754	    DRAFT, OPEN, PENDING, SETTLED, VOID;
755	
756	    /** Whether the claim counts toward claimed, due-total and every total. */
757	    public boolean counts() {
758	        return this == OPEN || this == PENDING || this == SETTLED;
759	    }
760	
761	    /** Whether the claim is still to be paid: OPEN or PENDING. */
762	    public boolean unpaid() {
763	        return this == OPEN || this == PENDING;
764	    }
765	
766	    /**
767	     * Whether a claim in this status may be moved to the given one by opening, settling or voiding it; a
768	     * PENDING claim leaves PENDING only by being approved, rejected or voided.
769	     */
770	    public boolean canBecome(ClaimStatus next) {
771	        return switch (next) {
772	            case OPEN -> this == DRAFT;
773	            case PENDING, SETTLED -> this == OPEN;
774	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
775	            case DRAFT -> false;
776	        };
777	    }
778	}
