package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim a person makes: an amount (two decimals), a date, a note and a status. A negative amount is a
 * correction, naming the number of the SETTLED claim of the same person it corrects.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The number the claim got when opened; null while a draft; a voided claim keeps it. */
    @Column(name = "claim_number")
    private Integer number;

    /** The sequence a period-numbered claim counts in ('P<period id>', or 'X' for no period); null otherwise. */
    @Column(name = "period_sequence")
    private String periodSequence;

    /** The claim's place in its period sequence; null for a sheet-wide number. */
    @Column(name = "period_seq_number")
    private Integer periodSeqNumber;

    /** The number as shown for a period-numbered claim (<period name>-<n>, or X-<n>); null otherwise. */
    @Column(name = "period_number")
    private String periodNumber;

    /** The user who opened the claim; null while a draft and once voided. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The due fixed when the claim was settled; null while not settled or when there was no rate. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** Whether the person's last statement bound the claim to statedDue. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the last statement bound the claim to; null while unbound or when it had none. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim a correction corrects; null for any other claim. */
    @Column(name = "corrects")
    private String corrects;

    /** The date of the claim a correction corrects, which its rounding goes by; null for any other claim. */
    @Column(name = "corrects_date")
    private LocalDate correctsDate;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
        this.corrects = corrects;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public LocalDate getCorrectsDate() {
        return correctsDate;
    }

    public void setCorrectsDate(LocalDate correctsDate) {
        this.correctsDate = correctsDate;
    }

    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects. */
    public LocalDate getRoundsBy() {
        return correctsDate != null ? correctsDate : date;
    }

    /** Whether the claim is a correction: its amount is negative. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public Integer getNumber() {
        return number;
    }

    public void setNumber(Integer number) {
        this.number = number;
    }

    /** Number the claim within a period sequence, shown as {@code label}. */
    public void setPeriodNumber(String sequence, int n, String label) {
        this.periodSequence = sequence;
        this.periodSeqNumber = n;
        this.periodNumber = label;
    }

    /** The number as shown: its period number, or its sheet-wide number; null while it has none. */
    public String getShownNumber() {
        return periodNumber != null ? periodNumber : number == null ? null : number.toString();
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (a statement it counts at). */
    public void bind(BigDecimal figure) {
        this.stated = true;
        this.statedDue = figure;
    }

    /** Release the claim to its live figure (a statement it does not count at). */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashSet;
import java.util.List;
import net.officefloor.hq.app.period.ClosedPeriodRefused;
import net.officefloor.hq.app.person.PersonController.PersonView;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.statement.StatementService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/**
 * A person's claims. Adding or editing a claim answers with the person it belongs to, carrying
 * their claims and claimed; so does opening, settling, approving, rejecting or voiding one. Opening a selection of claims
 * together answers how many were opened and how many refused. The signed-in user's name comes in the {@code X-User} header.
 */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /**
     * An amount with up to two decimals, negative for a correction, which names the number of the claim
     * it corrects; a blank date takes the sheet's today.
     */
    public record ClaimForm(@NotNull @Pattern(regexp = "-?\\d{1,12}(\\.\\d{1,2})?") String amount,
            LocalDate date, @Size(max = 500) String note, @Pattern(regexp = "[1-9]\\d{0,8}|.{1,100}-[1-9]\\d{0,8}") String corrects) {
    }

    /** A quick-add: a person's name and a claim's amount. */
    public record QuickAddForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount) {
    }

    /** The claims selected to be opened together. */
    public record BulkOpenForm(@NotNull @Size(max = 1000) List<@NotNull Long> claimIds) {
    }

    /** Why a PENDING claim is rejected. */
    public record RejectForm(@NotBlank @Size(max = 200) String reason) {
    }

    public record Refusal(String message) {
    }

    private final ClaimService claims;
    private final QuickAddService quick;
    private final BulkOpenService bulkOpen;
    private final PersonService people;
    private final RateService rates;
    private final StatementService statements;

    public ClaimController(ClaimService claims, QuickAddService quick, BulkOpenService bulkOpen, PersonService people,
            RateService rates, StatementService statements) {
        this.bulkOpen = bulkOpen;
        this.claims = claims;
        this.quick = quick;
        this.people = people;
        this.rates = rates;
        this.statements = statements;
    }

    @PostMapping("/people/{personId}/claims")
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody ClaimForm form) {
        String sheet = sheetId.trim();
        long id = claims.add(sheet, user.trim(), personId, new BigDecimal(form.amount()), form.date(), form.note(),
                form.corrects());
        return view(sheet, id);
    }

    /** Quick-add a DRAFT claim for a person by name, adding the person when the name is new. */
    @PostMapping("/quick-add")
    public PersonView quickAdd(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody QuickAddForm form) {
        String sheet = sheetId.trim();
        long id = quick.add(sheet, user.trim(), form.name(), new BigDecimal(form.amount()));
        return view(sheet, id);
    }

    @PutMapping("/claims/{claimId}")
    public PersonView edit(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody ClaimForm form) {
        String sheet = sheetId.trim();
        long id = claims.edit(sheet, user.trim(), claimId, new BigDecimal(form.amount()), form.date(), form.note(),
                form.corrects());
        return view(sheet, id);
    }

    @PostMapping("/claims/{claimId}/open")
    public PersonView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        return move(sheetId, claimId, user, ClaimStatus.OPEN);
    }

    /** Open the selected claims, numbered in list order; answers how many were opened and how many refused. */
    @PostMapping("/claims/bulk-open")
    public BulkOpenService.Result openAll(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody BulkOpenForm form) {
        return bulkOpen.open(sheetId.trim(), user.trim(), new LinkedHashSet<>(form.claimIds()));
    }

    @PostMapping("/claims/{claimId}/settle")
    public PersonView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        return move(sheetId, claimId, user, ClaimStatus.SETTLED);
    }

    /** A steward approves a PENDING claim, settling it. */
    @PostMapping("/claims/{claimId}/approve")
    public PersonView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, claims.approve(sheet, user.trim(), claimId));
    }

    /** A steward rejects a PENDING claim with a reason, putting it back to OPEN. */
    @PostMapping("/claims/{claimId}/reject")
    public PersonView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody RejectForm form) {
        String sheet = sheetId.trim();
        return view(sheet, claims.reject(sheet, user.trim(), claimId, form.reason().trim()));
    }

    @PostMapping("/claims/{claimId}/void")
    public PersonView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        return move(sheetId, claimId, user, ClaimStatus.VOID);
    }

    private PersonView move(String sheetId, long claimId, String user, ClaimStatus next) {
        String sheet = sheetId.trim();
        return view(sheet, claims.move(sheet, user.trim(), claimId, next));
    }

    private PersonView view(String sheetId, long personId) {
        return PersonView.of(people.get(sheetId, personId), claims.forPerson(sheetId, personId),
                rates.table(sheetId), statements.forPerson(sheetId, personId), people.patrons(sheetId, personId));
    }

    /** A claim dated inside a closed period: refused, nothing changed. */
    @ExceptionHandler(ClosedPeriodRefused.class)
    public ResponseEntity<Refusal> closed(ClosedPeriodRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** Another save took a quick-added person's name first: refused, nothing changed. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void nameInUse() {
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The claims on a sheet: listed per person newest first, added, edited and moved through their
 * statuses one at a time. Only a DRAFT can be edited. A voided claim keeps
 * its number, which is never reused; a claim opened while period numbering is on is numbered within its
 * period instead of sheet-wide. Settling a claim fixes its due at the rate its person's grade has then on the claim's date
 * (at least the sheet's floor then), or at the
 * figure a statement bound it to, plus the late charge it has then. No claim dated inside a closed period can be added, edited or moved,
 * and no claim dated after its person's retirement date can be added or edited to that date. A clerk
 * settling a claim whose due is above the sheet's clerk limit leaves it PENDING instead; a steward settles
 * anything, and approves a PENDING claim (settling it, its due fixed then) or rejects it with a reason
 * (back to OPEN); the user who opened a claim cannot approve it. A claim
 * with a negative amount is a correction: it is added or edited only when it names, by number, a SETTLED
 * claim of the same person, and only a correction names one.
 */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final RateService rates;
    private final Rollup rollup;
    private final PeriodService periods;
    private final AccessService access;
    private final ApplicationEventPublisher events;

    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets,
            SheetRepository sheetRows, RateService rates, Rollup rollup, PeriodService periods, AccessService access,
            ApplicationEventPublisher events) {
        this.access = access;
        this.rollup = rollup;
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.rates = rates;
        this.events = events;
    }

    /** Every claim on the sheet by the person who made it, each person's newest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<Claim>> bySheet(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
    }

    @Transactional(readOnly = true)
    public List<Claim> forPerson(String sheetId, long personId) {
        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
    }

    /** Add a claim; a date left out takes the sheet's today. Returns the person it belongs to. */
    @Transactional
    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        return add(sheetId, user, personId, amount, date, note, null);
    }

    /**
     * Add a claim, a correction naming the number of the claim it corrects; a date left out takes the
     * sheet's today. Returns the person it belongs to.
     */
    @Transactional
    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        periods.requireOpen(sheetId, on);
        requireNotRetired(person, on);
        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects);
        Rollup.Figures before = rollup.figures(sheetId);
        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
        claim.setCorrectsDate(correctsDate);
        claims.saveAndFlush(claim);
        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null));
        rollup.changed(sheetId, user, before);
        return personId;
    }

    /**
     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
     * added again instead), and an edit is refused when a closed period contains its date or the new one.
     * Returns the person it belongs to.
     */
    @Transactional
    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        periods.requireOpen(sheetId, claim.getDate(), on);
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
        }
        if (!on.equals(claim.getDate())) {
            people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
        }
        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
        Rollup.Figures before = rollup.figures(sheetId);
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setCorrectsDate(correctsDate);
        claim.setDate(on);
        claim.setNote(note == null ? "" : note);
        claims.flush();
        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
                claim.getDate(), claim.getShownNumber(), null));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Move a claim to a status; a move its status does not allow, settling by the user who opened
     * the claim, or moving a claim dated inside a closed period, is refused and changes nothing. Settling
     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
     * Returns the person it belongs to.
     */
    @Transactional
    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
        Claim claim = claim(sheetId, claimId);
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot settle it");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        if (next == ClaimStatus.OPEN) {
            giveNumber(sheetId, claim);
            claim.setOpenedBy(user);
        }
        String number = claim.getShownNumber();
        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
        String due = null;
        if (next == ClaimStatus.SETTLED) {
            BigDecimal fixed = dueNow(sheetId, claim, owner);
            if (access.canSettle(sheetId, user, fixed)) {
                claim.setSettledDue(fixed);
                due = fixed == null ? "n/a" : fixed.toPlainString();
            } else {
                next = ClaimStatus.PENDING;
            }
        }
        claim.setStatus(next);
        claims.flush();
        String person = owner == null ? "" : owner.getName();
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        };
        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
     * closed period is refused and nothing changes. Returns the person it belongs to.
     */
    @Transactional
    public long approve(String sheetId, String user, long claimId) {
        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
        if (user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
        BigDecimal fixed = dueNow(sheetId, claim, owner);
        claim.setSettledDue(fixed);
        claim.setStatus(ClaimStatus.SETTLED);
        claims.flush();
        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
     * period is refused and nothing changes. Returns the person it belongs to.
     */
    @Transactional
    public long reject(String sheetId, String user, long claimId, String reason) {
        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
        Rollup.Figures before = rollup.figures(sheetId);
        claim.setStatus(ClaimStatus.OPEN);
        claims.flush();
        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
                claim.getDate(), claim.getShownNumber(), null, reason));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
        }
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
        }
        return claim;
    }

    private Claim claim(String sheetId, long claimId) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        periods.requireOpen(sheetId, claim.getDate());
        return claim;
    }

    /** The claim's due now, its late charge frozen in, as settling fixes it. */
    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
    }

    /**
     * Give a claim being opened its number: while the sheet's period numbering from is set and the
     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
     * taking one at the same moment wait on each other, so no number is given twice or skipped.
     */
    private void giveNumber(String sheetId, Claim claim) {
        LocalDate from = sheets.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            claim.setNumber(sheets.nextClaimNumber(sheetId));
            return;
        }
        sheetRows.lockById(sheetId);
        Period period = periods.list(sheetId).stream().filter(p -> p.contains(claim.getDate()))
                .findFirst().orElse(null);
        String sequence = period == null ? "X" : "P" + period.getId();
        int n = claims.lastInSequence(sheetId, sequence) + 1;
        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
    }

    /**
     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
     * correction corrects (its rounding goes by it); null for any other claim.
     */
    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            if (corrects != null) {
                throw new ResponseStatusException(HttpStatus.CONFLICT,
                        "Only a correction (a negative amount) names a claim it corrects");
            }
            return null;
        }
        if (corrects == null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A negative amount is a correction; name the number of the settled claim it corrects");
        }
        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
                .map(Claim::getDate).findFirst()
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
                        "Claim " + corrects + " is not a settled claim of this person"));
    }

    /** Refuse a claim dated after its person's retirement date. */
    private static void requireNotRetired(Person person, LocalDate date) {
        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    person.getName() + " is retired from " + person.getRetiredFrom()
                            + "; a claim cannot be dated after that");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** The last place given in a period sequence on the sheet; 0 before any. */
    @Query("select coalesce(max(c.periodSeqNumber), 0) from Claim c where c.sheetId = :sheetId and c.periodSequence = :sequence")
    int lastInSequence(@Param("sheetId") String sheetId, @Param("sequence") String sequence);
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim was added ({@code CLAIM_ADDED}), edited ({@code CLAIM_EDITED}), opened
 * ({@code CLAIM_OPENED}), settled ({@code CLAIM_SETTLED}), left pending ({@code CLAIM_PENDING}), approved
 * ({@code CLAIM_APPROVED}), rejected ({@code CLAIM_REJECTED}) or voided ({@code CLAIM_VOIDED}) on a sheet.
 * The number is the claim's number, or null when it has none. The due is the due fixed by settling or
 * approving ({@code n/a} when there was no rate), or null when the event carries none. The reason is a
 * rejection's reason, or null when the event carries none.
 */
public record ClaimChanged(String event, String sheetId, String user, String person, BigDecimal amount,
        LocalDate date, String number, String due, String reason) {

    public ClaimChanged(String event, String sheetId, String user, String person, BigDecimal amount,
            LocalDate date, String number, String due) {
        this(event, sheetId, user, person, amount, date, number, due, null);
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling
 * one above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (back to
 * OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). Only OPEN, PENDING and SETTLED claims count
 * toward what is claimed.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether the claim counts toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still to be paid: OPEN or PENDING. */
    public boolean unpaid() {
        return this == OPEN || this == PENDING;
    }

    /**
     * Whether a claim in this status may be moved to the given one by opening, settling or voiding it; a
     * PENDING claim leaves PENDING only by being approved, rejected or voided.
     */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case PENDING, SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
    }
}

